var grid = new ArcDataGrid
{
    Label = "Q3 budget",
    Zebra = true,
    DefaultSort = new ArcGridSort { Key = "budget", Descending = true },
    Columns = new List<ArcGridColumn>
    {
        new() { Key = "project", Header = "Project", Width = 0, MinWidth = 120 },
        new() { Key = "budget", Header = "Budget", Width = 140, Align = ArcGridAlign.Right },
        new()
        {
            Key = "spent",
            Header = "Spent",
            Width = 120,
            Align = ArcGridAlign.Right,
            ValueGetter = row => row["budget"] is double budget && row["progress"] is double progress
                ? budget * progress / 100
                : null
        }
    },
    Rows = new List<ArcGridRow>
    {
        new() { Id = "r1", Values = { ["project"] = "Atlas redesign", ["budget"] = 48250d, ["progress"] = 64d } }
    }
};

grid.CellEdited += (_, edit) =>
    Console.WriteLine($"{edit.Column.Header}: {edit.OldValue} → {edit.NewValue}");
